"""Build 02_Assignments — one multi-sheet workbook per week."""
import pandas as pd
import openpyxl
from openpyxl.styles import Font, PatternFill, Alignment
from xl_helpers import *

CLEAN = "ETEH_Bootcamp/Datasets/CLEAN"

GOLD = PatternFill("solid", fgColor=GOLD)
GREEN = PatternFill("solid", fgColor=GREEN)
SUB = Font(name="Calibri", size=10, italic=True, color="595959")

# ---------- helpers ----------
def assign_sheet(wb, name, title, subtitle, tasks, data_hint="", points=0):
    ws = wb.create_sheet(name[:31])
    setup_sheet(ws, title, subtitle)
    r = 4
    r = section(ws, r, "Assignment tasks", ncols=7)
    for i, t in enumerate(tasks, 1):
        r = write_table(ws, r, ["#", "Task", "Instructions / deliverable"],
                        [[i, t[0], t[1]] for t in tasks[i-1:i]],
                        widths=[6, 46, 104], banded=True)
        r += 1
    if data_hint:
        r = section(ws, r, "Data to use", ncols=7)
        r = note(ws, r, data_hint, ncols=7, height=30)
    if points:
        r = section(ws, r, "Marks", ncols=7)
        r = note(ws, r, f"This module is worth {points} marks. See the week README for the total and submission rules.", ncols=7, height=24)
    return ws

def week_readme(wb, title, subtitle, week, modules_total, instructions, files):
    readme_sheet(wb, title, subtitle,
        [f"Week {week} assignment workbook — one sheet per module. Complete every task on the module sheet and submit as instructed."],
        files,
        instructions)

def make_week(filename, title, subtitle, week, readme_rows, sheets):
    wb = openpyxl.Workbook()
    week_readme(wb, title, subtitle, week, len(sheets), readme_rows[0], readme_rows[1])
    for name, t, s, tasks, hint, pts in sheets:
        assign_sheet(wb, name, t, s, tasks, hint, pts)
    wb.save(filename)
    print("saved", filename, "sheets=", wb.sheetnames)

